export default function Todo() {
  return (
    <>
      <Card sx={{ minWidth: 275, backgroundColor: "#083880", color: "#fff" }}>
        <CardContent>
          <Typography variant="h2">المهمه الاولي</Typography>
        </CardContent>
      </Card>
    </>
  );
}
